{"implementation": "def solve(case):
    nodes = case['nodes']
    core_distance = case['core_distance']
    distances = case['distances']
    n = len(nodes)
    if n == 0:
        return {'edges': [], 'total_weight': 0.0}
    # Map node to index for union-find
    node_to_idx = {node: i for i, node in enumerate(nodes)}
    # Build edges
    edges = []
    for src, tgt, d in distances:
        core_src = core_distance[src]
        core_tgt = core_distance[tgt]
        mr = max(core_src, core_tgt, d)
        # Canonicalize undirected endpoints: order by string
        if src < tgt:
            a, b = src, tgt
        else:
            a, b = tgt, src
        edges.append((mr, a, b))
    # Sort by mutual_reachability then by source, then target
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    # Union-Find
    parent = list(range(n))
    rank = [0] * n
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total_weight = 0.0
    for mr, a, b in edges:
        ia = node_to_idx[a]
        ib = node_to_idx[b]
        if union(ia, ib):
            mst_edges.append({'source': a, 'target': b, 'mutual_reachability': mr})
            total_weight += mr
            if len(mst_edges) == n - 1:
                break
    if len(mst_edges) != n - 1:
        raise ValueError('Disconnected graph: cannot form a spanning tree')
    return {'edges': mst_edges, 'total_weight': total_weight}"}
